#!/usr/bin/env python3
"""kb_old.py (.768): the two position kernels of .746-.767 (tnk_pos, the C7 family's pos_pair_divgap; tnk_pos_o, every other
processor's pos_pair_imask) for VXKBENCH only (src/vx_kbench_old.asm), as the bytes that were timed on the boards (they were tools/tnl_win.py's
'pos_c7' and 'pos_o' until R1, the reworked T&L, replaced them in the driver with tnq_gpos and tnq_pos). VXKBENCH times them beside the
driver's kernels on the same processor in the same run; they are never linked into the driver. Replaces tools/kb_ablate.py (.749B: the
cut-down copies of these two kernels; that study closed with T749B).
  python3 tools/kb_old.py"""
import sys
from pathlib import Path
HERE=Path(__file__).resolve().parent;sys.path.insert(0,str(HERE))
import tnl_asm
OLD={
 '_tnk_old_pos':
  '',
 '_tnk_old_pos_o':
  '',
}
def main():
 parts=[]
 for nm,hx in OLD.items():
  rows=tnl_asm.listed(nm,bytes.fromhex(hx))
  parts.append(tnl_asm.wasm(nm,rows))
 (HERE.parent/'src'/'vx_kbench_old.asm').write_text('; vx_kbench_old.asm: the position kernels of .746-.767 for VXKBENCH only (tools/kb_old.py); not in the driver since .768.\n.386\n.model flat\n.code\n'+'\n'.join(parts)+'\nend\n')
 # the same bytes for the host's run of VXKBENCH's rows (tests/test_kbench_frame.c)
 gs='.intel_syntax noprefix\n.text\n'+''.join('.globl %s\n'%n for n in OLD)
 for nm,hx in OLD.items():
  b=bytes.fromhex(hx);gs+=nm+':\n'+''.join(' .byte '+','.join('0x%02x'%x for x in b[i:i+16])+'\n' for i in range(0,len(b),16))
 (HERE.parent/'tests'/'kbench_old.s').write_text(gs)
 print(len(parts),'kernels')
if __name__=='__main__':main()
